 print(json.dumps({k:v for k,v in h.items() if k not in ['validation','candidate_diagnostics']},default=str))
 print('VALIDATION',json.dumps({k:v for k,v in h.get('validation',{}).items() if k"'!='"'slices'}))
PY"

